import { usePnlProfitText } from '@/hook/common/usePnlProfitText'
import { PumpToken, PumpTokenDetail } from '@/type/pump'
import { Block } from '@cetus/design'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { NoData, Table } from '@cetus/ui-kit'
import H5MapTable from '@cetus/ui-kit/src/components/H5MapTable'
import { HStack, Text, VStack } from '@chakra-ui/react'
import { useNavigate } from 'react-router-dom'
import MarketCapBlock from '../common/MarketCapBlock'
import SingleToken from '../common/SingleToken'
import RankingImg from './RankingImg'
const getColumns = (loading: boolean) => {
  return [
    {
      title: (
        <Text
          fontSize="14px"
          pl={{
            base: 0,
            lg: loading ? '0' : '36px !important'
          }}
        >
          Name (Symbol)
        </Text>
      ),
      key: 'name',
      tdConfig: {
        h: '60px',
        cursor: 'pointer'
      },
      render: ({ TokenDetail }: { TokenDetail: PumpTokenDetail }, index: number) => {
        return (
          <HStack
            w={{
              base: 'calc(100% - 120px)',
              lg: 'unset'
            }}
            justifyContent={{
              base: 'flex-end',
              lg: 'flex-start'
            }}
            align="center"
            pl="32px !important"
          >
            <RankingImg index={index} />
            <SingleToken
              token={TokenDetail}
              w={{
                base: 'unset',
                lg: '180px'
              }}
            />
          </HStack>
        )
      }
    },
    {
      title: <Text fontSize="14px">Market Cap</Text>,
      key: 'market_cap',
      render: (item: PumpToken) => {
        return <MarketCapBlock pumpToken={item} />
      }
    },
    {
      title: <Text fontSize="14px">24H%</Text>,
      key: 'price_change',
      render: ({ price_change_24h }: { price_change_24h: string }) => {
        const { color, percentText } = usePnlProfitText({ initNum: price_change_24h })
        return (
          <Text color={color} fontWeight="500">
            {percentText}
          </Text>
        )
      }
    }
  ]
}
function PriceIncreaseTable({ list, loading }: { list: PumpToken[]; loading: boolean }) {
  const { isApp } = useWindowWidth()
  const navigate = useNavigate()
  return (
    <VStack
      w={isApp ? '100%' : 'calc(50% - 10px)'}
      position="relative"
      mt={{ base: '12px', lg: '35px' }}
      gap="20px"
      p={{ base: '8px', lg: 0 }}
      background={{ base: 'ranking_list_h5_bg', lg: 'transparent' }}
    >
      <HStack w="100%" align="center" justifyContent="space-between">
        <Text fontSize="20px" color="launch_title" fontWeight="500">
          24H Price Increase
        </Text>
      </HStack>
      {!loading && list?.length == 0 ? (
        <NoData type="nodata" />
      ) : isApp ? (
        <H5MapTable<PumpToken>
          dataSource={list}
          columns={getColumns(loading)}
          rowKey="coin_type"
          loading={loading}
          itemSkeletonLength={3}
          rowStyle={{
            w: '100%',
            p: '8px',
            bg: 'bg_secondary',
            border: '1px solid',
            borderColor: 'border',
            borderRadius: '20px'
          }}
          onRowClick={item => {
            navigate(`/trade/${item?.coin_type}`)
          }}
        />
      ) : (
        <Block p="0" pt="24px" bg="ranking_table_bg" overflow="hidden">
          <Table<PumpToken>
            rowKey="coin_type"
            columns={getColumns(loading)}
            dataSource={list}
            skeletonLength={10}
            loading={loading}
            onRowClick={item => {
              navigate(`/trade/${item?.coin_type}`)
            }}
            rowStyle={{ h: '60px', cursor: 'pointer' }}
          />
        </Block>
      )}
    </VStack>
  )
}

export default PriceIncreaseTable
